import { describe, expect, setDefaultTimeout, test } from "bun:test"
import type { Feature } from "../../cad/history.ts"
import { DEFAULT_CUTTERS, findCutter, planOnly, runJob, type CamArtifact, type ManufacturingJob, type OperationSpec } from "./index.ts"
import { findMachine } from "./machines.ts"
import type { PostId } from "../post/types.ts"

setDefaultTimeout(100_000)

// The hole and feature breadth reaches a real job: planned from the part, generated by the kernel, posted and replayed.
const rect = (id: string, x: number, y: number, width: number, height: number): Feature => ({
  id, type: "sketch", plane: "XY", sketch: { entities: [], constraints: [], shapes: [{ id: `${id}r`, kind: "rectangle", at: [x, y], width, height }] }
})
const hole = (id: string, x: number, y: number, t: number, diameter: number, depth: number, over: Partial<Extract<Feature, { type: "hole" }>> = {}): Feature =>
  ({ id, type: "hole", plane: "XY", offset: t, at: [x, y], diameter, depth, ...over } as Feature)
const plate = (t: number, extra: Feature[]): Record<string, unknown> => ({
  id: "p", type: "parametric", name: "Plate", x: 0, y: 0, z: 0,
  history: { parameters: {}, features: [rect("base", 0, 0, 80, 50), { id: "plate", type: "extrude", sketch: "base", depth: t, operation: "new" }, ...extra] }
})
const job = (extra: Feature[], over: Partial<ManufacturingJob> = {}, t = 12): ManufacturingJob => ({
  schemaVersion: 1, id: "breadth", name: "Breadth plate", material: "6061", part: { kind: "elements", elements: [plate(t, extra)] },
  stock: { min: { x: -2, y: -2, z: 0 }, max: { x: 82, y: 52, z: t + 1 } }, machine: findMachine("vmc-standard")!, quality: { resolution: 0.5 }, ...over
})
const longDrill = { ...findCutter(DEFAULT_CUTTERS, "drill-4")!, id: "drill-4-long", name: "Drill Ø4 long series", fluteLength: 70, stickout: 90 }
const ok = (r: ReturnType<typeof runJob>): CamArtifact => {
  if (r.status !== "ok") throw new Error(r.issues.map((i) => i.message).join("; "))
  return r.value
}
const drills = (ops: ReadonlyArray<OperationSpec>) => ops.filter((o): o is Extract<OperationSpec, { strategy: "drill" }> => o.strategy === "drill")

describe("hole breadth in a planned job", () => {
  const sink = hole("c", 30, 25, 12, 5, 12, { kind: "countersink", headDiameter: 10, angle: 90 })

  test("without the breadth the countersink is not planned as a cycle; with it, the kernel generates and replays the cycle", () => {
    const plain = planOnly(job([sink]))
    expect(plain.status).toBe("ok")
    if (plain.status === "ok") expect(drills(plain.value.operations).some((o) => o.cycle !== undefined)).toBe(false)

    const a = ok(runJob(job([sink], { breadth: { holeCycles: true } })))
    const cone = a.operations.find((o) => o.strategy === "drill" && o.toolId.startsWith("csk"))
    expect(cone?.status).toBe("ok")
    expect(a.notes).toContainEqual(expect.stringMatching(/^H1-countersink-cycle: c planned/))
    expect(a.issues.filter((i) => i.severity === "error")).toEqual([])
    expect(a.nc).toContain("G82")
  })

  test("a deep hole is pecked by the kernel and the replay agrees with the program", () => {
    const tools = [...DEFAULT_CUTTERS, longDrill]
    const a = ok(runJob(job([hole("d", 40, 25, 30, 4, 28)], { breadth: { holeCycles: true }, tools }, 30)))
    expect(a.notes).toContainEqual(expect.stringMatching(/^H2-deep-hole: d planned/))
    const deep = a.operations.find((o) => o.strategy === "drill" && o.toolId === "drill-4-long")
    expect(deep?.status).toBe("ok")
    expect(a.issues.filter((i) => i.severity === "error")).toEqual([])
    // Pecked: the tip goes down in several steps, not once.
    expect(a.nc.split("\n").filter((l) => /Z-?\d/.test(l) && /F\d/.test(l)).length).toBeGreaterThan(3)
  })

  test("a deep hole without a long drill is refused with the reason in the notes, never drilled short", () => {
    const a = ok(runJob(job([hole("d", 40, 25, 30, 4, 28)], { breadth: { holeCycles: true } }, 30)))
    expect(a.notes).toContainEqual(expect.stringMatching(/^H2-deep-hole: d refused - no Ø4 drill/))
    expect(a.operations.some((o) => o.strategy === "drill")).toBe(false)
  })

  test("a back-bore bores up from the underside through the pilot, and the replay finds no gouge", () => {
    const under: Feature = { id: "under", type: "plane", from: { kind: "points", points: [[0, 0, 0], [1, 0, 0], [0, -1, 0]] } } as Feature
    const bb = { id: "bb", type: "hole", plane: "under", at: [40, -25], diameter: 12, depth: 30, kind: "counterbore", headDiameter: 16, headDepth: 12 } as Feature
    const a = ok(runJob(job([under, bb], { breadth: { holeCycles: true } }, 30)))
    expect(a.notes).toContainEqual(expect.stringMatching(/^H3-back-bore: bb planned/))
    expect(a.operations.find((o) => o.strategy === "drill" && o.toolId.startsWith("boringbar"))?.status).toBe("ok")
    expect(a.issues.filter((i) => i.severity === "error")).toEqual([])
    // The underside is invisible to the height field, so the back-boring is judged on the tri-dexel replay of every move: its claims
    // are decided there (with the error declared), and the faces that look away from this one setup still keep the job at preview.
    for (const id of ["no-rapid-in-stock", "holder-clearance", "no-gouge", "material-removed"]) {
      expect(a.claims.find((c) => c.id === id)?.status, id).toBe("passed")
      expect(a.claims.find((c) => c.id === id)?.detail, id).toMatch(/tri-dexel/)
    }
    expect(a.claims.find((c) => c.id === "part-coverage")?.status).toBe("unresolved")
    expect(a.release).not.toBe("verified-program")
  })

  test("a back-bore with an insert 4 mm wide is judged with the reach of its corners and still passes the pilot", () => {
    const under: Feature = { id: "under", type: "plane", from: { kind: "points", points: [[0, 0, 0], [1, 0, 0], [0, -1, 0]] } } as Feature
    const bb = { id: "bb", type: "hole", plane: "under", at: [40, -25], diameter: 12, depth: 30, kind: "counterbore", headDiameter: 16, headDepth: 12 } as Feature
    const bar = DEFAULT_CUTTERS.find((t) => t.kind === "boringbar")!
    const tools = [...DEFAULT_CUTTERS.filter((t) => t.kind !== "boringbar"), { ...bar, id: "boringbar-wide", insertWidth: 4 }]
    const a = ok(runJob(job([under, bb], { breadth: { holeCycles: true }, tools }, 30)))
    expect(a.operations.find((o) => o.strategy === "drill" && o.toolId === "boringbar-wide")?.status).toBe("ok")
    for (const id of ["no-rapid-in-stock", "holder-clearance"]) expect(a.claims.find((c) => c.id === id)?.status, id).toBe("passed")
  })

  // The planned back-bore with the outline of its pilot declared: a round one of the pilot's size, or a slot the real pilot is not.
  const withOutline = (outline: ReadonlyArray<{ x: number; y: number }>, post?: PostId): CamArtifact => {
    const under: Feature = { id: "under", type: "plane", from: { kind: "points", points: [[0, 0, 0], [1, 0, 0], [0, -1, 0]] } } as Feature
    const bb = { id: "bb", type: "hole", plane: "under", at: [40, -25], diameter: 12, depth: 30, kind: "counterbore", headDiameter: 16, headDepth: 12 } as Feature
    const machine = findMachine("vmc-standard")!
    const base = job([under, bb], { breadth: { holeCycles: true }, ...(post !== undefined ? { machine: { ...machine, post } } : {}) }, 30)
    const planned = planOnly(base)
    if (planned.status !== "ok") throw new Error("plan")
    const operations = planned.value.operations.map((o) => (o.strategy === "drill" && o.cycle?.kind === "back-bore" ? { ...o, cycle: { ...o.cycle, pilotOutline: outline } } : o))
    return ok(runJob({ ...base, operations }))
  }
  const ring = (r: number, n = 96): Array<{ x: number; y: number }> => Array.from({ length: n }, (_, k) => ({ x: r * Math.cos((2 * Math.PI * k) / n), y: r * Math.sin((2 * Math.PI * k) / n) }))

  test("a back-bore with the outline of its round pilot is turned and shifted by the search, and the stopped tooth passes the real pilot", () => {
    const a = withOutline(ring(6))
    expect(a.operations.find((o) => o.strategy === "drill" && o.toolId.startsWith("boringbar"))?.status).toBe("ok")
    expect(a.issues.filter((i) => i.severity === "error")).toEqual([])
    for (const id of ["no-rapid-in-stock", "holder-clearance", "no-gouge", "material-removed"]) expect(a.claims.find((c) => c.id === id)?.status, id).toBe("passed")
    // A control with a fixed mark leaves the angle 0 (plain M19), and the undercut is still the whole disc the spinning head sweeps.
    expect(a.nc).toMatch(/M19\b(?! [PR])/)
  })

  // A hexagon turned 15 degrees, inscribed in the round Ø12 pilot: smaller than the hole, and too small for the bar with its clearance.
  const hexagon = Array.from({ length: 6 }, (_, k) => ({ x: 6 * Math.cos(((15 + 60 * k) * Math.PI) / 180), y: 6 * Math.sin(((15 + 60 * k) * Math.PI) / 180) }))

  test("a post that writes an angle writes the orientation the search found; an outline the bar cannot pass is refused on either post, naming what the control allows", () => {
    const haas = withOutline(ring(6), "haas")
    expect(haas.operations.find((o) => o.strategy === "drill" && o.toolId.startsWith("boringbar"))?.status).toBe("ok")
    expect(haas.nc).toMatch(/M19 [PR]\d/)
    for (const id of ["no-rapid-in-stock", "holder-clearance", "no-gouge", "material-removed"]) expect(haas.claims.find((c) => c.id === id)?.status, id).toBe("passed")
    const refusedOnHaas = withOutline(hexagon, "haas")
    expect(refusedOnHaas.operations.find((o) => o.strategy === "drill" && o.toolId.startsWith("boringbar"))?.status).toBe("failed")
    expect(refusedOnHaas.issues.map((i) => i.message).join(" ")).toMatch(/does not pass the pilot outline: at its best angle/)
    const refusedOnFanuc = withOutline(hexagon)
    expect(refusedOnFanuc.operations.find((o) => o.strategy === "drill" && o.toolId.startsWith("boringbar"))?.status).toBe("failed")
    expect(refusedOnFanuc.issues.map((i) => i.message).join(" ")).toMatch(/control's mark only/)
  })

  test("an outline that says the pilot is a long slot, when the drilled pilot is round, is caught: the tooth the search stands outside the round wall", () => {
    const slot = [{ x: -8.5, y: -4.5 }, { x: 8.5, y: -4.5 }, { x: 8.5, y: 4.5 }, { x: -8.5, y: 4.5 }]
    const a = withOutline(slot)
    expect(a.claims.find((c) => c.id === "no-rapid-in-stock")?.status).not.toBe("passed")
    expect(a.release).not.toBe("verified-program")
  })

  test("a back-bore replay that stopped at its budget is not read as passed", () => {
    const under: Feature = { id: "under", type: "plane", from: { kind: "points", points: [[0, 0, 0], [1, 0, 0], [0, -1, 0]] } } as Feature
    const bb = { id: "bb", type: "hole", plane: "under", at: [40, -25], diameter: 12, depth: 30, kind: "counterbore", headDiameter: 16, headDepth: 12 } as Feature
    const a = ok(runJob(job([under, bb], { breadth: { holeCycles: true } }, 30), { replayWorkLimit: 2e5 }))
    const gouge = a.claims.find((c) => c.id === "no-gouge")
    expect(gouge?.status).toBe("unresolved")
    expect(a.release).not.toBe("verified-program")
  })

  test("named features are recognised on the exact solid and the notes say what became of them", () => {
    const a = ok(runJob(job([], { breadth: { namedFeatures: true }, quality: { resolution: 0.5, deburr: 1 } })))
    expect(a.issues.filter((i) => i.severity === "error")).toEqual([])
    // A plain plate has no slot, groove or band: nothing is invented.
    expect(a.notes.filter((n) => /^N\d/.test(n))).toEqual([])
  })

  test("meshes cannot be recognised: the job says so instead of silently dropping the request", () => {
    const cube = { positions: [0, 0, 0, 10, 0, 0, 10, 10, 0, 0, 10, 0, 0, 0, 10, 10, 0, 10, 10, 10, 10, 0, 10, 10], indices: [0, 2, 1, 0, 3, 2, 4, 5, 6, 4, 6, 7, 0, 1, 5, 0, 5, 4, 1, 2, 6, 1, 6, 5, 2, 3, 7, 2, 7, 6, 3, 0, 4, 3, 4, 7] }
    const r = runJob({ ...job([], { breadth: { namedFeatures: true } }), part: { kind: "meshes", meshes: [cube] }, stock: { min: { x: -1, y: -1, z: 0 }, max: { x: 11, y: 11, z: 11 } } })
    if (r.status !== "ok") throw new Error(r.issues.map((i) => i.message).join("; "))
    expect(r.value.notes).toContainEqual(expect.stringMatching(/^Named features need CAD elements/))
  })
})

describe("tilted drilling in a planned job", () => {
  const side: Feature = { id: "s", type: "hole", plane: "YZ", offset: 80, at: [25, 6], diameter: 5, depth: 25 } as Feature
  test("a side hole is drilled along its own axis on the trunnion machine; on a three-axis machine the request is reported, not faked", () => {
    const five = ok(runJob(job([side], { breadth: { tilted: true }, machine: findMachine("trunnion-5ax")! }, 12)))
    expect(five.notes).toContainEqual(expect.stringMatching(/^H4-tilted-drilling: s planned/))
    expect(five.nc).toMatch(/\bA-?\d/)
    expect(five.issues.filter((i) => i.severity === "error")).toEqual([])
    const three = ok(runJob(job([side], { breadth: { tilted: true } }, 12)))
    expect(three.notes).toContainEqual(expect.stringMatching(/^Tilted drilling needs a five-axis machine/))
  })
})
